        return "0/1"
    elif N == 1:
        return "1/1"
    else:
        numerator = N // 2
        denominator = N - numerator
        if N % 2 == 0:
            return f"{numerator}/{denominator}"
        else:
            return f"{denominator}/{numerator}"

