def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)
    for i in range(n):
        for j in range(V, volumes[i] - 1, -1):
            dp[j] = max(dp[j], dp[j - volumes[i]] + volumes[i])
    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c: str, shift: int) -> str:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            return chr((ord(c) - base + shift) % 26 + base)
        return c

    key_length = len(key)
    plaintext = ""
    for i in range(len(ciphertext)):
        key_char = key[i % key_length]
        shift = ord(key_char) - ord('A') if key_char.isupper() else ord(key_char) - ord('a')
        plaintext += shift_char(ciphertext[i], -shift)
    return plaintext

def mod_inverse(a, b):
    if b == 0:
        return None
    x, y = 0, 1
    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x, y = y - quotient * x, x
    return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0

    for day, (school_hours, extra_hours) in enumerate(schedule):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day + 1

    return most_unhappy_day if max_unhappiness > 0 else 0

