def min_groups(w, n, prices):
    prices.sort()
    groups = 0
    current_group_price = 0

    for price in prices:
        if current_group_price + price <= w:
            current_group_price += price
        else:
            groups += 1
            current_group_price = price

    return groups + 1 if current_group_price <= w else groups

